look.customCSS:
/* ───── 猫猫 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/200px 200px,linear-gradient(180deg,#EEF3F9,#DCE6F2) !important;position:relative !important}
[data-wk="chat"]::before{content:"" !important;position:absolute !important;left:24px !important;bottom:96px !important;width:54px !important;height:54px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;z-index:0 !important;animation:ktRoll 6s ease-in-out infinite !important}
@keyframes ktRoll{0%,100%{transform:translateX(0) rotate(0)}50%{transform:translateX(14px) rotate(60deg)}}
[data-wk="body"]{background:url("data:image/svg+xml;base64,") center top/100% 760px repeat-y local !important;position:relative !important;z-index:1 !important;padding-top:30px !important}
/* 顶栏：奶白，下沿波浪布边挂小东西，右边垂一条会摆的尾巴 */
[data-wk="chathead"]{background:#FBFAF7 !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;overflow:visible !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:calc(100% - 10px) !important;height:52px !important;background:url("data:image/svg+xml;base64,") center top/100% auto no-repeat !important;pointer-events:none !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;right:14px !important;top:calc(100% + 2px) !important;width:34px !important;height:82px !important;background:url("data:image/svg+xml;base64,") center top/contain no-repeat !important;transform-origin:50% 0 !important;animation:ktTail 3.6s ease-in-out infinite !important;pointer-events:none !important;z-index:6 !important}
@keyframes ktTail{0%,100%{transform:rotate(-6deg)}50%{transform:rotate(8deg)}}
[data-wk="headink"]{color:#4B5470 !important}
[data-wk="headdim"]{color:#8C9BB8 !important}
[data-wk="chatback"] svg{stroke:#4B5470 !important}
[data-wk="chatmore"]{font-size:0 !important;color:transparent !important;width:44px !important;min-width:44px !important;height:30px !important;background:url("data:image/svg+xml;base64,") center/40px auto no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="sameroom"]{width:38px !important;min-width:38px !important;height:38px !important;font-size:0 !important;padding:0 !important;overflow:visible !important;background:url("data:image/svg+xml;base64,") center/32px 32px no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：猫耳＋粉项圈＋小金铃 */
[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:50% !important}
[data-wk="avatar"] *{border-radius:50% !important}
img[data-wk="avatar"],[data-wk="avatar"] img{clip-path:circle(50%) !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-26% !important;top:-40% !important;bottom:-33% !important;background:url("data:image/svg+xml;base64,") center top/contain no-repeat !important;pointer-events:none !important;z-index:2 !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::before{content:"" !important;position:absolute !important;width:52px !important;height:55px !important;left:-8px !important;top:calc(50% - 30px) !important;background:url("data:image/svg+xml;base64,") center top/contain no-repeat !important;pointer-events:none !important;z-index:2 !important}

/* 气泡：肉垫形，尾巴是一颗小肉球 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:24px 24px 24px 24px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{border-bottom-right-radius:8px !important;box-shadow:0 3px 0 rgba(140,155,184,.25) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{border-bottom-left-radius:8px !important;box-shadow:0 3px 0 rgba(140,155,184,.22) !important}
[data-wk="bubble"][data-kind="text"]::before{content:none !important}
[data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;bottom:-6px !important;width:14px !important;height:14px !important;border-radius:50% !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{right:-5px !important;background:#CFDAEA !important;border:2px solid #8C9BB8 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after{left:-5px !important;background:#fff !important;border:2px solid #8C9BB8 !important}

/* 已读：前面一条小鱼 */
[data-wk="meta"]{color:#8C9BB8 !important}
[data-wk="meta"]::before{content:"" !important;display:inline-block !important;width:16px !important;height:8px !important;margin-right:4px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
/* 时间：两头各一颗肉垫的小胶囊 */
[data-wk="time"] > span{background:#fff url("data:image/svg+xml;base64,") 10px center/12px 12px no-repeat !important;border:1.5px solid #8C9BB8 !important;border-radius:999px !important;padding:2px 14px 2px 28px !important;color:#4B5470 !important}

/* 底栏 */
[data-wk="composer"]{background:#FBFAF7 !important;border-top:2px solid #8C9BB8 !important}
[data-wk="chatinput"]{background:#fff !important;border:2px solid #8C9BB8 !important;border-radius:999px !important;color:#4B5470 !important}
[data-wk="chatinput"]::placeholder{color:#A6B1C7 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;width:38px !important;height:38px !important;min-width:38px !important;align-self:center !important;transition:transform .12s !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.86) !important}

/* 正在输入：一只小爪子从边上伸出来扒拉 */
[data-wk="bubble"][data-kind="typing"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{width:16px !important;height:16px !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}

/* 系统提示、拍一拍、动描：一行小字，前面一条小鱼 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important;text-align:center !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{color:#8C9BB8 !important;font-style:normal !important}
[data-wk="note"][data-part="pat"]{background:#fff !important;border:1.5px solid #8C9BB8 !important;border-radius:999px !important;color:#4B5470 !important;padding:2px 12px !important}
[data-wk="narrink"]{background:rgba(255,255,255,.7) !important;border:1.5px solid #8C9BB8 !important;border-radius:16px !important;color:#4B5470 !important}

/* 整个猫耳框垫在头像底下，位置不动，只是头像图压在上面 */
button[data-wk="avatar"],span[data-wk="avatar"]{isolation:isolate !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{z-index:0 !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]){isolation:isolate !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]) > [data-wk="avatar"]{position:relative !important;z-index:1 !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::before{z-index:0 !important}

/* 气泡返工：圆滚滚的软糖，顶角探一对小猫耳，侧边三根胡须，尾巴是一个小肉垫 */
[data-wk="bubble"][data-kind="text"]{border-radius:26px !important;margin-top:10px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#DCE6F3,#C9D6E8) !important;border-bottom-right-radius:26px !important;box-shadow:inset 0 2px 0 rgba(255,255,255,.7),0 4px 0 rgba(140,155,184,.28) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(180deg,#fff,#F6F8FC) !important;border-bottom-left-radius:26px !important;box-shadow:inset 0 2px 0 #fff,0 4px 0 rgba(140,155,184,.22) !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;top:-11px !important;width:34px !important;height:14px !important;border:none !important;pointer-events:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{right:22px !important;left:auto !important;transform:rotate(4deg) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{left:22px !important;right:auto !important;transform:rotate(-4deg) !important}
[data-wk="bubble"][data-kind="text"]::after{bottom:-10px !important;width:24px !important;height:22px !important;border:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{right:-4px !important;transform:rotate(25deg) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;border-radius:0 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after{left:-4px !important;transform:rotate(-25deg) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;border-radius:0 !important}

/* 毛线固定在屏幕上，毛线团沿着这根线来回滚（offset-path 用同一条线，按屏幕比例换算） */
[data-wk="body"]{background:transparent !important}
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/200px 200px,linear-gradient(180deg,#EEF3F9,#DCE6F2) !important}
[data-wk="chat"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:0 !important;bottom:0 !important;background:url("data:image/svg+xml;base64,") 0 0/390px 760px no-repeat !important;pointer-events:none !important;z-index:0 !important}
[data-wk="chat"]::before{left:0 !important;top:0 !important;bottom:auto !important;width:40px !important;height:40px !important;margin:-20px 0 0 -20px !important;transform:none !important;translate:91px 227px !important;animation:none !important}
/* 手机支持「跟着滑动走」时：往上滑一点，毛线团就顺着线往前滚一点，滑到底它就滚到线尾；不支持就乖乖停在线上 */
[data-wk="chat"]{timeline-scope:--ktscroll !important}
[data-wk="body"]{scroll-timeline:--ktscroll y !important}
[data-wk="chat"]::before{animation:ktAlong linear both,ktSpin linear both !important;animation-timeline:--ktscroll,--ktscroll !important}
@keyframes ktAlong{0.00%{translate:299px 704px}4.17%{translate:298px 684px}8.33%{translate:298px 662px}12.50%{translate:298px 640px}16.67%{translate:298px 616px}20.83%{translate:299px 590px}25.00%{translate:301px 562px}29.17%{translate:304px 531px}33.33%{translate:308px 496px}37.50%{translate:311px 460px}41.67%{translate:305px 431px}45.83%{translate:291px 408px}50.00%{translate:270px 390px}54.17%{translate:244px 375px}58.33%{translate:215px 363px}62.50%{translate:185px 350px}66.67%{translate:156px 337px}70.83%{translate:130px 322px}75.00%{translate:109px 302px}79.17%{translate:94px 277px}83.33%{translate:89px 246px}87.50%{translate:94px 218px}91.67%{translate:108px 193px}95.83%{translate:129px 171px}100.00%{translate:155px 151px}}
@keyframes ktSpin{from{rotate:0deg}to{rotate:-1440deg}}

/* ───── 猫猫 · 第二批：卡片 ───── */
/* 卡片统一：奶白软糖块、蓝灰描边、底下一层厚边，像气泡一家 */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="voice"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:#fff !important;border:2px solid #8C9BB8 !important;border-radius:22px !important;box-shadow:0 4px 0 #C3CEE0 !important;color:#4B5470 !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#4B5470 !important;border-color:#C3CEE0 !important}

/* 转账：猫爪印收据——顶上一排小鱼齿孔，收了盖一个粉肉垫 */
[data-wk="transfercard"]{position:relative !important;overflow:visible !important;padding-top:26px !important;background:radial-gradient(circle at 0 64%,#DCE6F2 8px,transparent 9px),radial-gradient(circle at 100% 64%,#DCE6F2 8px,transparent 9px),#fff !important}
[data-wk="transfercard"]::before{content:"喵 · 小鱼干收据" !important;position:absolute !important;left:16px !important;top:8px !important;font-size:10px !important;letter-spacing:.16em !important;color:#8C9BB8 !important;padding-left:18px !important;background:url("data:image/svg+xml;base64,") 0 center/12px 12px no-repeat !important}
[data-wk="transferlabel"]{color:#8C9BB8 !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#4B5470 !important;font-weight:700 !important}
[data-wk="transferrule"]{border:none !important;height:6px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiA2Jz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS42JyBmaWxsPScjOEM5QkI4JyBvcGFjaXR5PScuNScvPjwvc3ZnPg==") 0 0/12px 6px repeat-x !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:#EEF3F9 !important;border-radius:0 0 20px 20px !important}
[data-wk="transfernote"]::before{content:"附言：" !important;color:#8C9BB8 !important}
[data-wk="transferbtn"]{border-radius:999px !important}
[data-wk="transferbtn"][data-part="take"]{background:#8C9BB8 !important;color:#fff !important;border:none !important;box-shadow:0 3px 0 #6F7D99 !important}
[data-wk="transferbtn"][data-part="back"]{background:#fff !important;color:#8C9BB8 !important;border:1.5px solid #8C9BB8 !important}
[data-wk="transferseal"]{border:2px solid #8C9BB8 !important;box-shadow:none !important;color:#8C9BB8 !important;background:#EEF3F9 !important;border-radius:50% !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"],[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"]{width:68px !important;height:68px !important;flex-shrink:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;opacity:1 !important;padding:34px 0 0 !important;transform:rotate(-12deg) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(10deg) !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"] *,[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"] *{color:#fff !important;font-size:12px !important;letter-spacing:0 !important;white-space:nowrap !important;font-weight:700 !important}
[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"] > div:nth-child(2),[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"] > div:nth-child(2){display:none !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.8 !important}

/* 红包：一罐小鱼罐头 */
[data-wk="rpcard"]{background:linear-gradient(180deg,#fff,#EEF3F9) !important;border:2px solid #8C9BB8 !important;border-radius:22px !important;box-shadow:0 4px 0 #C3CEE0 !important;padding-left:96px !important;min-height:92px !important;position:relative !important;overflow:visible !important}
[data-wk="rpcard"] *{color:#4B5470 !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:74px !important;height:64px !important;margin-top:-34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;animation:ktWob 2.4s ease-in-out infinite !important;transform-origin:50% 100% !important}
@keyframes ktWob{0%,100%{transform:rotate(-3deg)}50%{transform:rotate(3deg)}}
[data-wk="rpcard"]::after{content:"小鱼罐头" !important;position:absolute !important;left:24px !important;bottom:5px !important;font-size:10px !important;letter-spacing:.2em !important;color:#8C9BB8 !important}
[data-wk="rpflap"],[data-wk="rpseal"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{background:#EEF3F9 !important;box-shadow:none !important;filter:none !important}
[data-wk="rpcard"][data-status="done"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:.6 !important;animation:none !important}
[data-wk="rpcard"][data-status="done"]::after{content:"吃光啦" !important}
/* 拆开前：一大罐，按钮是拉环 */
[data-wk="rpenvelope"][data-stage="closed"]{background:url("data:image/svg+xml;base64,") 0 0/200px 200px,linear-gradient(180deg,#fff,#DCE6F2) !important;border:2.5px solid #8C9BB8 !important;border-radius:30px !important;box-shadow:0 6px 0 #C3CEE0 !important}
[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rparc"]{background:#FBFAF7 !important;border-top:2.5px solid #8C9BB8 !important}
[data-wk="rpenvelope"] *{color:#4B5470 !important}
[data-wk="rpopenbtn"]{background:#fff url("data:image/svg+xml;base64,") center/62% auto no-repeat !important;border:2.5px solid #8C9BB8 !important;box-shadow:0 4px 0 #C3CEE0 !important;animation:ktWob 1.6s ease-in-out infinite !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
/* 拆开后 */
[data-wk="rpenvelope"][data-stage="open"]{background:url("data:image/svg+xml;base64,") 0 0/200px 200px,#EEF3F9 !important;border:2.5px solid #8C9BB8 !important;border-radius:30px !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"][data-part="top"]{background:#DCE6F2 !important;border-bottom:2.5px solid #8C9BB8 !important;box-shadow:none !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"][data-part="top"]::after{content:none !important}
[data-wk="rpavatar"]{box-shadow:0 0 0 3px #fff,0 0 0 5px #8C9BB8 !important;border-radius:50% !important}
[data-wk="rpamount"]{color:#4B5470 !important;background:none !important}
[data-wk="rpstatus"],[data-wk="rpwish"]{color:#8C9BB8 !important}
[data-wk="rpclose"]{background:#fff !important;border:2px solid #8C9BB8 !important;color:#8C9BB8 !important}

/* 照片：拍立得，顶上探一对猫耳 */
[data-wk="photocard"]{position:relative !important;overflow:visible !important;padding:8px 8px 22px !important;margin-top:10px !important}
[data-wk="photocard"]::before{content:"" !important;position:absolute !important;top:-11px !important;left:20px !important;width:34px !important;height:14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="photoface"]{background:url("data:image/svg+xml;base64,") 0 0/120px 120px,#DCE6F2 !important;border-radius:14px !important;border:none !important}
[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#4B5470 !important}

/* 语音：毛线团在前，声波是一截截毛线 */
[data-wk="voice"] > *{background:transparent !important;box-shadow:none !important;border:none !important;color:#4B5470 !important}
[data-wk="voice"]{padding-left:40px !important;position:relative !important}
[data-wk="voice"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:24px !important;height:24px !important;margin-top:-12px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important}
[data-wk="voicewave"] span{background:#8C9BB8 !important;border-radius:3px !important}
/* 天气 */
[data-wk="wxcardsky"]{background:linear-gradient(170deg,#EEF3F9,#DCE6F2) !important;color:#4B5470 !important}
[data-wk="wxcardsky"] *{color:#4B5470 !important}
[data-wk="wxcardsky"] svg{stroke:#8C9BB8 !important}
[data-wk="wxcardsay"]{background:#fff !important;color:#4B5470 !important;border-top:2px solid #DCE6F2 !important}
/* 位置：钉一条小鱼 */
[data-wk="geopin"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:none !important;border:none !important;width:26px !important;height:26px !important}
[data-wk="geopin"] *{opacity:0 !important}
[data-wk="geopinstem"]{background:#8C9BB8 !important}
/* 名片 */
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2px #fff,0 0 0 4px #8C9BB8 !important}

/* 拍一拍：小肉垫胶囊；通话结束胶囊同款 */
