/* 线上气泡也换软猫耳 */
[data-wk="bubble"][data-kind="text"]::before{top:-14px !important;width:46px !important;height:17px !important;transform:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{right:24px !important;background:url("data:image/svg+xml;base64,") center bottom/100% 100% no-repeat !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{left:24px !important;background:url("data:image/svg+xml;base64,") center bottom/100% 100% no-repeat !important}

/* 短气泡耳朵自动缩：宽度跟着气泡走（最多 46px、最少 28px），底边始终压住边框 3px */
[data-wk="bubble"][data-kind="text"]::before{width:clamp(28px,40%,46px) !important;height:auto !important;aspect-ratio:64/22 !important;top:auto !important;bottom:calc(100% - 3px) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{right:clamp(12px,14%,24px) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{left:clamp(12px,14%,24px) !important}

/* 顶栏挂件底下垫一层渐隐的雾蓝：往上滑的字到这里就淡出去，不跟毛线球、铃铛糊在一起 */
[data-wk="chathead"]::after{height:64px !important;background:url("data:image/svg+xml;base64,") center top/100% auto no-repeat,linear-gradient(180deg,#EEF3F9 0,#EEF3F9 62%,rgba(238,243,249,0) 100%) !important}
/* 名字＝项圈上挂的小名牌：蓝灰描边的圆角牌子，左边一颗金铃铛 */
[data-wk="chathead"] [data-wk="headname"] > [data-wk="headink"]{display:inline-flex !important;max-width:100% !important;background:#fff url("data:image/svg+xml;base64,") 7px center/14px 14px no-repeat !important;border:1.5px solid #8C9BB8 !important;border-radius:11px !important;padding:0 8px 0 24px !important;line-height:1.35 !important;box-shadow:0 2px 0 #C3CEE0 !important;font-size:15px !important}
[data-wk="chathead"] [data-wk="headname"] > [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"] > [data-wk="headdim"]{font-size:9px !important;opacity:.75 !important;margin:1px 0 0 6px !important;line-height:1.2 !important}
